import json, random, sys
from driver import run
from ref_replay import ref_replay

def invalid_events(P, R, seq):
    for e in seq:
        if e[0] == "send":
            if not (0 <= e[1] < P and 0 <= e[2] < R):
                return True
        elif e[0] == "retry":
            if not (0 <= e[1] < P):
                return True
        else:
            if not (0 <= e[1] <= 200000):
                return True
    return False

seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
niter = int(sys.argv[2]) if len(sys.argv) > 2 else 400
random.seed(seed)
bad = 0
for tcase in range(niter):
    P = random.randint(1, 4)
    R = random.choice([0, 1, 2, 3, 5])
    D = 0 if R == 0 else random.randint(0, 3)
    inputs = [[[random.randint(-5, 5) for _ in range(D)] for _ in range(R)]
              for _ in range(P)]
    nslots = random.randint(1, 4)
    window = random.randint(1, nslots)
    nev = random.randint(1, 60)
    seq = []
    evs = []
    live_ids_hint = 0
    for i in range(nev):
        c = random.choice(["send", "send", "send", "retry", "deliver",
                           "deliver", "deliver", "drop", "duplicate"])
        if c == "send" and R:
            r = random.randint(0, P - 1)
            q = random.randint(0, R - 1)
            seq.append(["send", r, q]); evs.append(("send", r, q))
        elif c == "retry":
            r = random.randint(0, P - 1)
            seq.append(["retry", r]); evs.append(("retry", r, 0))
        else:
            pid = random.randint(0, max(3, i * 4 + 2))
            seq.append([c, pid]); evs.append((c, pid, 0))
    assert not invalid_events(P, R, seq)
    req = {"op": "replay", "inputs": inputs, "slots": nslots, "window": window,
           "events": seq}
    try:
        exp = ref_replay(P, R, D, inputs, nslots, window, evs)
    except RuntimeError as e:
        if "LIMIT" in str(e):
            exp = {"error": "E_LIMIT"}
        else:
            raise
    got = run(json.dumps(req))[0][0]
    if got != exp:
        bad += 1
        print("MISMATCH case", tcase)
        print("req:", json.dumps(req))
        print("exp:", json.dumps(exp, sort_keys=True))
        print("got:", json.dumps(got, sort_keys=True))
        if bad >= 3:
            break
print("done seed", seed, "mismatches:", bad, "of", niter)
